package com.huy.enterprise.order; import com.huy.enterprise.common.BaseEntity; import com.huy.enterprise.common.enums.PurchaseOrderStatus; import com.huy.enterprise.supplier.Supplier; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; @Getter @Setter @Entity @Table(name="purchase_orders") public class PurchaseOrder extends BaseEntity {@Column(name="order_code",nullable=false,unique=true,length=100) private String orderCode; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="supplier_id") private Supplier supplier; @Column(name="order_date",nullable=false) private LocalDate orderDate; @Column(name="expected_delivery_date") private LocalDate expectedDeliveryDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private PurchaseOrderStatus status=PurchaseOrderStatus.DRAFT; @Column(name="total_amount",nullable=false,precision=15,scale=2) private BigDecimal totalAmount=BigDecimal.ZERO; private String notes; @OneToMany(mappedBy="purchaseOrder",cascade=CascadeType.ALL,orphanRemoval=true) private List<PurchaseOrderItem> items=new ArrayList<>();}
